mapper.select:
SELECT CAST(rc.room_category_id AS CHAR) AS roomCategoryId, rc.name AS roomCategoryName, CAST(ch.channel_id AS CHAR) AS channelId, ch.channel_name AS channelName, commission_info.commission_rate AS commissionRate, goods_info.product_name AS productName, COALESCE(goods_info.normal_price, rc.weekday_price_cent, 0) AS normalPrice, COALESCE(goods_info.normal_actual_sale_price, goods_info.normal_price, rc.weekday_price_cent, 0) AS normalActualSalePrice FROM room_category rc LEFT JOIN ( SELECT rel.camp_id AS camp_id, rel.room_category_id AS room_category_id, ca.channel_id AS channel_id, ca.channel_name AS channel_name, MIN(ca.account_id) AS sort_account_id FROM channel_room_category_rel rel JOIN channel_account ca ON ca.account_id = rel.account_id AND ca.camp_id = rel.camp_id WHERE ca.status = 'authorized' AND rel.shelf_status = 'on_shelf' AND rel.audit_status = 'approved' GROUP BY rel.camp_id, rel.room_category_id, ca.channel_id, ca.channel_name ) ch ON ch.camp_id = rc.camp_id AND ch.room_category_id = rc.room_category_id LEFT JOIN ( SELECT idx.camp_id AS camp_id, idx.room_category_id AS room_category_id, CAST( ROUND( CAST(JSON_UNQUOTE(JSON_EXTRACT(dp.commission_rule_json, '$.rate')) AS DECIMAL(10, 4)) * 100, 0 ) AS UNSIGNED ) AS commission_rate FROM distribution_product dp JOIN ( SELECT dp.camp_id AS camp_id, grr.room_category_id AS room_category_id, MIN(dp.distribution_product_id) AS distribution_product_id FROM distribution_product dp JOIN goods_room_category_rel grr ON grr.goods_id = dp.goods_id WHERE dp.status = 1 GROUP BY dp.camp_id, grr.room_category_id ) idx ON idx.distribution_product_id = dp.distribution_product_id ) commission_info ON commission_info.camp_id = rc.camp_id AND commission_info.room_category_id = rc.room_category_id LEFT JOIN ( SELECT idx.camp_id AS camp_id, idx.room_category_id AS room_category_id, gm.name AS product_name, gm.selling_price_cent AS normal_price, gm.selling_price_cent AS normal_actual_sale_price FROM goods_main gm JOIN ( SELECT gm.camp_id AS camp_id, grr.room_category_id AS room_category_id, MIN(gm.goods_id) AS goods_id FROM goods_main gm JOIN goods_room_category_rel grr ON grr.goods_id = gm.goods_id WHERE gm.is_deleted = 0 GROUP BY gm.camp_id, grr.room_category_id ) idx ON idx.goods_id = gm.goods_id ) goods_info ON goods_info.camp_id = rc.camp_id AND goods_info.room_category_id = rc.room_category_id WHERE rc.camp_id = #{campId} AND rc.status = 1 AND rc.is_deleted = 0
AND rc.room_category_id IN
#{roomCategoryId}
AND ch.channel_id IN
#{channelId}
ORDER BY rc.sort_no ASC, rc.room_category_id ASC, ch.sort_account_id ASC, ch.channel_id ASC

SELECT CAST(rc.room_category_id AS CHAR) AS roomCategoryId, rc.name AS roomCategoryName, COALESCE( MAX(CASE WHEN rps.biz_date = ( SELECT MIN(inner_rps.biz_date) FROM room_price_snapshot inner_rps WHERE inner_rps.camp_id = rc.camp_id AND inner_rps.room_category_id = rc.room_category_id AND inner_rps.price_type = 'retail' AND inner_rps.channel_id = 0 AND inner_rps.status = 'active' ) THEN rps.price_cent END), rc.weekday_price_cent, 0 ) AS normalPrice, COALESCE( MAX(CASE WHEN rps.biz_date = ( SELECT MIN(inner_rps.biz_date) FROM room_price_snapshot inner_rps WHERE inner_rps.camp_id = rc.camp_id AND inner_rps.room_category_id = rc.room_category_id AND inner_rps.price_type = 'retail' AND inner_rps.channel_id = 0 AND inner_rps.status = 'active' ) THEN rps.price_cent END), rc.weekday_price_cent, 0 ) AS normalActualSalePrice, GROUP_CONCAT(CONCAT(DATE_FORMAT(rps.biz_date, '%Y-%m-%d'), ':', rps.price_cent) ORDER BY rps.biz_date ASC SEPARATOR ',') AS statusPricesText FROM room_category rc LEFT JOIN room_price_snapshot rps ON rps.camp_id = rc.camp_id AND rps.room_category_id = rc.room_category_id AND rps.price_type = 'retail' AND rps.channel_id = 0 AND rps.status = 'active' WHERE rc.camp_id = #{campId} AND rc.status = 1 AND rc.is_deleted = 0
AND rc.room_category_id IN
#{roomCategoryId}
AND rc.poi_id IN
#{poiId}
GROUP BY rc.room_category_id, rc.name, rc.weekday_price_cent, rc.sort_no ORDER BY rc.sort_no ASC, rc.room_category_id ASC
